'use strict';

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const clone = x => JSON.parse(JSON.stringify(x));
const uid = () => Math.random().toString(36).slice(2,10);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fmtDate=s=>{try{return new Date(s).toLocaleDateString('en-CA',{month:'short',day:'numeric'})}catch{return s||''}};
const fmtTime=s=>{const n=Math.max(0,Math.floor(s||0));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};

async function api(method,path,body){
  const opt={method,headers:{}};
  if(body!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}
  const r=await fetch(path,opt); const t=await r.text(); let o={}; try{o=t?JSON.parse(t):{}}catch{o={error:t}}
  if(!r.ok) throw new Error(o.error||('HTTP '+r.status)); return o;
}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2200)}
function modal(html){$('#modal').innerHTML=html;$('#modalOverlay').classList.remove('hidden')}
function closeModal(){$('#modalOverlay').classList.add('hidden')}
$('#modalOverlay').addEventListener('mousedown',e=>{if(e.target.id==='modalOverlay')closeModal()});

const COLORS=['#17211b','#1f4e37','#8c3b24','#c9881e','#245c9b','#7d4ca3','#e85b8f','#ffffff'];
let S={folders:[],notes:[],fitz:false,lan:'localhost',port:8766};
let NOTE=null, FILTER='all', FOLDER=null, LISTGRID=false, SORT='updated';
let TOOL='pen', COLOR=COLORS[0], SIZE=4, ZOOM=.56, PAGE=0;
let undoHistory=new Map(),redoHistory=new Map(),activeStroke=null,draftShape=null,selection=null,dragSelection=null,laserStroke=null;
let saveTimer=null, saveInFlight=false, pendingSave=false;
let imgCache=new Map();
let mediaRecorder=null, mediaChunks=[],recordStart=0,recordTick=null,audioStream=null;
let recognition=null,transcribing=false,sharedToken=null,sharedMode=null,sharedPoll=null;
let penSeenAt=0;

const canvas=$('#inkCanvas'), overlay=$('#overlayCanvas'), stage=$('#pageStage');
let RS=1;
function renderScale(p){const dpr=window.devicePixelRatio||1;const cap=Math.sqrt(16000000/Math.max(1,p.width*p.height));return Math.max(.5,Math.min(Math.max(1,ZOOM*dpr),cap,4))}
function sizeCanvases(){const p=page();if(!p)return;const r=renderScale(p);const W=Math.round(p.width*r),H=Math.round(p.height*r);if(canvas.width!==W||canvas.height!==H){canvas.width=W;canvas.height=H;overlay.width=W;overlay.height=H}RS=W/p.width;ctx.setTransform(RS,0,0,RS,0,0);octx.setTransform(RS,0,0,RS,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';octx.imageSmoothingQuality='high'}
function hiUrl(u){return u&&u.startsWith('/pdfpage/')&&!u.includes('v=hi')?u+(u.includes('?')?'&':'?')+'v=hi':u}
function penOnlyPref(){try{return localStorage.getItem('vn_penonly')==='1'}catch(e){return false}}
const ctx=canvas.getContext('2d'), octx=overlay.getContext('2d');

function defaultContent(paper='blank'){
  return {version:1,activePage:0,paper,pages:[{id:uid(),name:'Page 1',paper,width:1600,height:2200,strokes:[],objects:[],background:null}],settings:{penOnly:true,snap:false}};
}
function page(){return NOTE?.content?.pages?.[PAGE]||null}
function historyStack(store){const id=page()?.id;if(!id)return[];if(!store.has(id))store.set(id,[]);return store.get(id)}
function normalizeContent(content,paper='blank'){const d=defaultContent(paper);if(!content||!Array.isArray(content.pages)||!content.pages.length)return d;content.pages=content.pages.filter(Boolean).map((p,i)=>({id:p.id||uid(),name:p.name||`Page ${i+1}`,paper:p.paper||paper,width:clamp(+p.width||1600,200,8000),height:clamp(+p.height||2200,200,8000),strokes:Array.isArray(p.strokes)?p.strokes:[],objects:Array.isArray(p.objects)?p.objects:[],background:p.background||null}));if(!content.pages.length)return d;content.settings=content.settings||{penOnly:true,snap:false};content.activePage=clamp(+content.activePage||0,0,content.pages.length-1);return content}
function folderName(id){return S.folders.find(f=>f.id==id)?.name||''}
function currentEndpoint(){return sharedToken?'/api/shared/'+sharedToken:'/api/notes/'+NOTE.id}

async function boot(){
  const p=location.pathname.match(/^\/s\/([^/]+)$/); if(p){sharedToken=p[1];await loadShared();return}
  S=await api('GET','/api/bootstrap');
  renderLibrary(); renderList(); bindUI(); applyTheme(localStorage.getItem('vn_theme')||'autumn'); setTool('pen'); setColor(COLOR); setSize(SIZE);
  const q=new URLSearchParams(location.search); if(q.get('note')) selectNote(+q.get('note'));
}

async function loadShared(){
  try{NOTE=await api('GET','/api/shared/'+sharedToken);sharedMode=NOTE.shared_mode;if(sharedMode==='view')document.body.classList.add('presentation');$('#library').classList.add('hidden');$('#noteListPane').classList.add('hidden');$('#topbar').classList.add('hidden');$('#editor').classList.remove('hidden');$('#emptyState').classList.add('hidden');$('#classbar').classList.remove('hidden');$('#classInfo').textContent=sharedMode==='edit'?'Collaborative whiteboard — student':'Student view — read only';NOTE.content=normalizeContent(NOTE.content,NOTE.paper);PAGE=NOTE.content.activePage||0;bindUI();hydrateEditor();if(sharedMode!=='edit') $('#classbar').querySelector('b').textContent='STUDENT VIEW';startSharedPolling();}catch(e){document.body.innerHTML='<div style="padding:40px;font-family:sans-serif">Invalid or disabled VanoNote link.</div>'}
}
function startSharedPolling(){clearInterval(sharedPoll);sharedPoll=setInterval(async()=>{if(!NOTE||saveInFlight)return;try{const n=await api('GET','/api/shared/'+sharedToken);if(n.revision>NOTE.revision){NOTE=n;NOTE.content=normalizeContent(NOTE.content,NOTE.paper);PAGE=sharedMode==='view'?NOTE.content.activePage:clamp(PAGE,0,NOTE.content.pages.length-1);hydrateEditor(false)}}catch{}},900)}

function bindUI(){
  if(bindUI.done)return;bindUI.done=true;
  $('#libToggle').onclick=()=>{if(innerWidth<=600){if(document.body.classList.contains('libopen'))document.body.classList.remove('libopen');else{document.body.classList.add('libopen');document.body.classList.remove('listopen')}}else if(NOTE&&innerWidth>850){document.body.classList.toggle('noteFocus')}else document.body.classList.toggle('libopen')};
  $('#newNote').onclick=()=>App.newNote(); $('#newFolder').onclick=newFolder;
  $('#search').oninput=()=>renderList(); $('#gridBtn').onclick=()=>{LISTGRID=!LISTGRID;renderList()};
  $('#sortBtn').onclick=()=>{SORT=SORT==='updated'?'title':'updated';renderList()};
  $$('.navitem').forEach(b=>b.onclick=()=>{$$('.navitem,.folder').forEach(x=>x.classList.remove('on'));b.classList.add('on');FILTER=b.dataset.filter;FOLDER=null;$('#listTitle').textContent=b.textContent.trim().replace(/\d+$/,'');renderList();if(innerWidth<=600){document.body.classList.add('listopen');document.body.classList.remove('libopen')}});
  $('#noteTitle').oninput=e=>{if(!NOTE||sharedMode==='view')return;NOTE.title=e.target.value;scheduleSave();updateMetaTitle()};
  $('#noteTitle').onblur=()=>saveNow();
  $$('.tool').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
  $('#customColor').oninput=e=>setColor(e.target.value); $('#size').oninput=e=>setSize(+e.target.value);$('#sizeDown').onclick=()=>setSize(SIZE-1);$('#sizeUp').onclick=()=>setSize(SIZE+1);
  $('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#addPageBtn').onclick=addPage;$('#pagePlus').onclick=addPage;$('#paperBtn').onclick=openTemplates;$('#importBtn').onclick=()=>$('#importFile').click();
  $('#importFile').onchange=importFiles;$('#audioBtn').onclick=toggleRecording;$('#recordToggle').onclick=toggleRecording;$('#transcribeBtn').onclick=toggleTranscription;
  $('#plainText').oninput=e=>{if(!NOTE||sharedMode==='view')return;NOTE.plain_text=e.target.value;scheduleSave()};
  $('#transcript').oninput=e=>{if(!NOTE||sharedMode==='view')return;NOTE.transcript=e.target.innerText;scheduleSave()};
  $('#presentBtn').onclick=enterPresentation;$('#exitPresent').onclick=exitPresentation;$('#shareBtn').onclick=openShare;$('#classShare').onclick=openShare;
  $('#prevPageClass').onclick=()=>setPage(PAGE-1);$('#nextPageClass').onclick=()=>setPage(PAGE+1);
  $('#templatesBtn').onclick=openTemplates;$('#flashcardsBtn').onclick=()=>{if(NOTE){$('#studyPane').classList.remove('hidden');$('#audioPane,#textPane').classList.add('hidden');$$('.inspTabs button').forEach(x=>x.classList.toggle('on',x.dataset.tab==='study'))}else toast('Open a note')};
  $('#backupBtn').onclick=backup;$('#settingsBtn').onclick=openSettings;$('#themeBtn').onclick=toggleTheme;
  $('#moreBtn').onclick=openMore;$('#penOnlyBtn').onclick=togglePenOnly;$('#splitBtn').onclick=openSplit;
  $('#summaryBtn').onclick=localSummary;$('#genCardsBtn').onclick=generateCards;$('#quizBtn').onclick=runQuiz;$('#mathBtn').onclick=insertLatex;
  $$('[data-md]').forEach(b=>b.onclick=()=>wrapTypedText(b.dataset.md));
  $$('.inspTabs button').forEach(b=>b.onclick=()=>{$$('.inspTabs button').forEach(x=>x.classList.toggle('on',x===b));$$('.inspPane').forEach(x=>x.classList.add('hidden'));$('#'+b.dataset.tab+'Pane').classList.remove('hidden')});
  $('#colors').innerHTML=COLORS.map(c=>`<button class="swatch" data-c="${c}" style="background:${c}"></button>`).join(''); $$('#colors .swatch').forEach(b=>b.onclick=()=>setColor(b.dataset.c));
  canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);
  overlay.addEventListener('pointerdown',pointerDown);overlay.addEventListener('pointermove',pointerMove);overlay.addEventListener('pointerup',pointerUp);overlay.addEventListener('pointercancel',pointerUp);
  $('#zoomOutBtn').onclick=()=>setZoom(ZOOM/1.15);$('#zoomInBtn').onclick=()=>setZoom(ZOOM*1.15);$('#fitWidthBtn').onclick=fitZoom;
  window.addEventListener('keydown',keyHandler);window.addEventListener('resize',fitZoom);
}

function renderLibrary(){
  const alive=S.notes.filter(n=>!n.deleted_at);$('#allCount').textContent=alive.length;$('#favCount').textContent=alive.filter(n=>n.favorite).length;$('#trashCount').textContent=S.notes.filter(n=>n.deleted_at).length;
  $('#folderList').innerHTML=S.folders.map(f=>`<button class="folder" data-id="${f.id}"><span class="folderDot" style="background:${esc(f.color)}"></span><span>${esc(f.name)}</span><span class="count">${alive.filter(n=>n.folder_id==f.id).length}</span></button>`).join('');
  $$('#folderList .folder').forEach(b=>b.onclick=()=>{$$('.navitem,.folder').forEach(x=>x.classList.remove('on'));b.classList.add('on');FILTER='folder';FOLDER=+b.dataset.id;$('#listTitle').textContent=folderName(FOLDER);renderList();if(innerWidth<=600){document.body.classList.add('listopen');document.body.classList.remove('libopen')}});
}
function noteFilter(n){
  const q=($('#search')?.value||'').trim().toLowerCase();
  if(FILTER==='trash'){if(!n.deleted_at)return false}else if(n.deleted_at)return false;
  if(FILTER==='favorite'&&!n.favorite)return false;
  if(FILTER==='recent'){const d=new Date(n.updated_at);if(Date.now()-d.getTime()>7*864e5)return false}
  if(FILTER==='folder'&&n.folder_id!=FOLDER)return false;
  if(q&&!((n.title+' '+(n.plain_text||'')+' '+(n.transcript||'')+' '+(n.tags||'')).toLowerCase().includes(q)))return false;
  return true;
}
function renderList(){
  let arr=S.notes.filter(noteFilter); arr.sort((a,b)=>SORT==='title'?a.title.localeCompare(b.title):(b.updated_at||'').localeCompare(a.updated_at||''));
  const el=$('#noteList');el.className=LISTGRID?'noteCards grid':'noteCards';
  el.innerHTML=arr.length?arr.map(n=>`<div class="noteCard ${NOTE?.id==n.id?'on':''}" data-id="${n.id}"><h3>${n.favorite?'<span class="star">★</span> ':''}${esc(n.title)}</h3><p>${esc((n.plain_text||n.transcript||'Handwritten note').slice(0,110))}</p><div class="noteMeta"><span>${fmtDate(n.updated_at)}</span><span>${n.kind==='pdf'?'PDF':'Note'}</span><span class="folderTag">${esc(folderName(n.folder_id)||'No folder')}</span></div></div>`).join(''):'<div class="listEmpty">No notes here.</div>';
  $$('#noteList .noteCard').forEach(c=>c.onclick=()=>selectNote(+c.dataset.id));
}
async function selectNote(id){
  if(NOTE&&NOTE.id!==id)await saveNow();
  try{NOTE=await api('GET','/api/notes/'+id);document.body.classList.add('noteFocus');document.body.classList.remove('listopen','libopen');NOTE.content=normalizeContent(NOTE.content,NOTE.paper);PAGE=clamp(NOTE.content.activePage||0,0,NOTE.content.pages.length-1);undoHistory=new Map();redoHistory=new Map();hydrateEditor();renderList();history.replaceState(null,'','?note='+id)}catch(e){toast(e.message)}
}
function hydrateEditor(refit=true){
  if(!NOTE)return;$('#emptyState').classList.add('hidden');$('#editor').classList.remove('hidden');$('#noteTitle').value=NOTE.title||'';$('#plainText').value=NOTE.plain_text||'';$('#transcript').innerText=NOTE.transcript||'';$('#penOnlyBtn').classList.toggle('on',penOnlyPref());renderAttachments();renderPages();setPage(PAGE,false);if(refit)setTimeout(fitZoom,20);updateMetaTitle();
}
function updateMetaTitle(){const m=S.notes.find(x=>x.id==NOTE?.id);if(m){m.title=NOTE.title;m.updated_at=NOTE.updated_at||m.updated_at;renderList()}}

const App={
  async newNote(){
    if(sharedToken)return; const folder=FOLDER||null;
    const n=await api('POST','/api/notes',{title:'New note',folder_id:folder,paper:'blank'}); S.notes.unshift({...n,content:undefined,attachments:undefined});renderLibrary();renderList();await selectNote(n.id);$('#noteTitle').focus();$('#noteTitle').select();
  }
}; window.App=App;
async function newFolder(){modal(`<div class="modalHead"><h2>New folder</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="field"><label>Name</label><input id="mfName" value="New folder"></div><div class="field"><label>Color</label><input id="mfColor" type="color" value="#355e4a"></div><div class="modalActions"><button onclick="closeModal()">Cancel</button><button class="primary" id="mfOk">Create</button></div>`);$('#mfName').select();$('#mfOk').onclick=async()=>{const f=await api('POST','/api/folders',{name:$('#mfName').value,color:$('#mfColor').value});S.folders.push(f);closeModal();renderLibrary();toast('Folder created')}}

function setTool(t){TOOL=t;$$('.tool').forEach(b=>b.classList.toggle('on',b.dataset.tool===t));overlay.style.cursor=t==='text'?'text':t==='eraser'?'cell':t==='select'?'crosshair':'crosshair';selection=null;drawOverlay()}
function setColor(c){COLOR=c;$('#customColor').value=/^#[0-9a-f]{6}$/i.test(c)?c:'#17211b';$$('.swatch').forEach(b=>b.classList.toggle('on',b.dataset.c.toLowerCase()===c.toLowerCase()))}
function setSize(n){SIZE=clamp(+n||1,1,40);$('#size').value=SIZE;$('#sizeLabel').textContent=SIZE}
function togglePenOnly(){const v=!penOnlyPref();try{localStorage.setItem('vn_penonly',v?'1':'0')}catch(e){}$('#penOnlyBtn').classList.toggle('on',v);toast(v?'Pen only: the mouse and touch do not draw':'Mouse, trackpad and pen all draw')}
function pushUndo(){const p=page();if(!p)return;const undo=historyStack(undoHistory);undo.push(clone({strokes:p.strokes,objects:p.objects}));if(undo.length>60)undo.shift();redoHistory.set(p.id,[]);updateUndoButtons()}
function undo(){const p=page(),undo=historyStack(undoHistory),redo=historyStack(redoHistory);if(!p||!undo.length)return;redo.push(clone({strokes:p.strokes,objects:p.objects}));const x=undo.pop();p.strokes=x.strokes;p.objects=x.objects;selection=null;renderCurrent();scheduleSave();updateUndoButtons()}
function redo(){const p=page(),undo=historyStack(undoHistory),redo=historyStack(redoHistory);if(!p||!redo.length)return;undo.push(clone({strokes:p.strokes,objects:p.objects}));const x=redo.pop();p.strokes=x.strokes;p.objects=x.objects;selection=null;renderCurrent();scheduleSave();updateUndoButtons()}
function updateUndoButtons(){$('#undoBtn').disabled=!historyStack(undoHistory).length;$('#redoBtn').disabled=!historyStack(redoHistory).length}

function setPage(i,save=true){if(!NOTE)return;i=clamp(i,0,NOTE.content.pages.length-1);PAGE=i;NOTE.content.activePage=i;const p=page();stage.style.width=(p.width*ZOOM)+'px';stage.style.height=(p.height*ZOOM)+'px';renderCurrent();renderPages();updateUndoButtons();$('#pageStatus').textContent=`Page ${i+1} / ${NOTE.content.pages.length}`;$('#classPage').textContent=`${i+1} / ${NOTE.content.pages.length}`;if(save)scheduleSave()}
function addPage(){if(!NOTE||sharedMode==='view')return;const base=page();NOTE.content.pages.push({id:uid(),name:'Page '+(NOTE.content.pages.length+1),paper:base?.paper||NOTE.paper||'blank',width:base?.width||1600,height:base?.height||2200,strokes:[],objects:[],background:null});setPage(NOTE.content.pages.length-1);scheduleSave()}
function deletePage(){if(!NOTE||sharedMode==='view'||NOTE.content.pages.length<=1)return toast('You must keep at least one page');if(!confirm('Delete this page?'))return;const removed=NOTE.content.pages[PAGE];NOTE.content.pages.splice(PAGE,1);undoHistory.delete(removed.id);redoHistory.delete(removed.id);PAGE=clamp(PAGE,0,NOTE.content.pages.length-1);setPage(PAGE);scheduleSave()}
function renderPages(){if(!NOTE)return;$('#pageThumbs').innerHTML=NOTE.content.pages.map((p,i)=>`<div class="thumb ${i===PAGE?'on':''}" data-i="${i}"><canvas class="thumbCanvas" width="90" height="120"></canvas><span>${i+1}</span></div>`).join('');$$('.thumb').forEach(th=>{th.onclick=()=>setPage(+th.dataset.i);const tc=th.querySelector('canvas'),tctx=tc.getContext('2d');drawPageTo(tctx,NOTE.content.pages[+th.dataset.i],90,120,true)});
}
function setZoom(z){if(!NOTE)return;const p=page();ZOOM=clamp(z,.25,2.4);stage.style.width=(p.width*ZOOM)+'px';stage.style.height=(p.height*ZOOM)+'px';clearTimeout(window._rsT);window._rsT=setTimeout(()=>{const q=page();if(q&&Math.abs(renderScale(q)-RS)>.05)renderCurrent()},140);$('#zoomStatus').textContent=Math.round(ZOOM*100)+'%'}
function fitZoom(){if(!NOTE)return;const v=$('#canvasViewport');const p=page();if(!v||!p)return;const w=Math.max(700,v.clientWidth-40);setZoom(w/p.width)}

function drawPaper(c,p,w,h,thumb=false){
  const paper=p.paper||'blank'; c.save();c.fillStyle=paper==='blackboard'?'#173128':'#fffefb';c.fillRect(0,0,w,h);
  const sx=w/(p.width||w),sy=h/(p.height||h);
  if(paper==='ruled'){c.strokeStyle='#c8d9ec';c.lineWidth=1;for(let y=90*sy;y<h;y+=70*sy){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}c.strokeStyle='#e7a7a7';c.beginPath();c.moveTo(115*sx,0);c.lineTo(115*sx,h);c.stroke()}
  if(paper==='grid'){c.strokeStyle='#d8e1dd';c.lineWidth=.8;for(let x=50*sx;x<w;x+=50*sx){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=50*sy;y<h;y+=50*sy){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}}
  if(paper==='dots'){c.fillStyle='#b8c1bd';for(let x=50*sx;x<w;x+=50*sx)for(let y=50*sy;y<h;y+=50*sy){c.beginPath();c.arc(x,y,thumb?.7:1.4,0,Math.PI*2);c.fill()}}
  if(paper==='cornell'){c.strokeStyle='#c8d9ec';c.lineWidth=1;for(let y=120*sy;y<h-190*sy;y+=70*sy){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}c.strokeStyle='#c6b7a0';c.lineWidth=2;c.beginPath();c.moveTo(300*sx,0);c.lineTo(300*sx,h-200*sy);c.moveTo(0,h-200*sy);c.lineTo(w,h-200*sy);c.stroke()}
  if(paper==='blackboard'){c.strokeStyle='rgba(255,255,255,.05)';for(let y=20;y<h;y+=25){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}}
  c.restore();
}
function loadImage(url,cb,err=()=>{}){if(imgCache.has(url)){const im=imgCache.get(url);if(im.complete&&im.naturalWidth)cb(im);else{im.addEventListener('load',()=>cb(im),{once:true});im.addEventListener('error',err,{once:true})}return}const im=new Image();imgCache.set(url,im);im.onload=()=>cb(im);im.onerror=err;im.src=url}
function drawPageTo(c,p,w=p.width,h=p.height,thumb=false){
  const sx=w/p.width,sy=h/p.height;
  const paintInk=()=>{c.save();c.scale(sx,sy);for(const s of p.strokes||[])drawStroke(c,s);for(const o of p.objects||[])drawObject(c,o);c.restore()};
  const base=im=>{c.save();c.clearRect(0,0,w,h);drawPaper(c,p,w,h,thumb);if(im)c.drawImage(im,0,0,w,h);c.restore();paintInk()};
  if(p.background?.url){const bu=thumb?p.background.url:hiUrl(p.background.url);const cached=imgCache.get(bu);if(cached?.complete&&cached.naturalWidth)base(cached);else{const old=imgCache.get(p.background.url);base(old&&old.complete&&old.naturalWidth?old:null);loadImage(bu,im=>base(im),()=>loadImage(p.background.url,im=>base(im)))}}else base(null);
}
function renderCurrent(){const p=page();if(!p)return;sizeCanvases();drawPageTo(ctx,p,p.width,p.height,false);drawOverlay()}
function drawStroke(c,s){
  if(s.kind==='shape')return drawShape(c,s);
  const pts=s.pts||[];if(!pts.length)return;c.save();c.lineCap='round';c.lineJoin='round';c.strokeStyle=s.color||'#111';c.globalAlpha=s.tool==='highlighter'?.28:1;
  if(pts.length===1){c.fillStyle=s.color||'#111';c.globalAlpha=s.tool==='highlighter'?.28:1;c.beginPath();c.arc(pts[0].x,pts[0].y,Math.max(1,s.size*(pts[0].p||.5)/2),0,Math.PI*2);c.fill();c.restore();return}
  for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i];let pr=(a.p+b.p)/2;if(!pr||pr<.05)pr=.5;let width=s.size*(s.tool==='highlighter'?2.7:(s.tool==='calligraphy'?(0.65+pr*1.8):(0.6+pr*.9)));c.lineWidth=Math.max(.6,width);c.beginPath();const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;if(i===1){c.moveTo(a.x,a.y);c.lineTo(mx,my)}else{const z=pts[i-2];c.moveTo((z.x+a.x)/2,(z.y+a.y)/2);c.quadraticCurveTo(a.x,a.y,mx,my)}if(i===pts.length-1)c.lineTo(b.x,b.y);c.stroke()}
  c.restore();
}
function drawShape(c,s){c.save();c.strokeStyle=s.color||'#111';c.lineWidth=s.size||3;c.lineCap='round';c.lineJoin='round';const {x1,y1,x2,y2}=s;c.beginPath();if(s.tool==='line'){c.moveTo(x1,y1);c.lineTo(x2,y2)}else if(s.tool==='rect'){c.rect(Math.min(x1,x2),Math.min(y1,y2),Math.abs(x2-x1),Math.abs(y2-y1))}else if(s.tool==='ellipse'){c.ellipse((x1+x2)/2,(y1+y2)/2,Math.abs(x2-x1)/2,Math.abs(y2-y1)/2,0,0,Math.PI*2)}else if(s.tool==='arrow'){c.moveTo(x1,y1);c.lineTo(x2,y2);const a=Math.atan2(y2-y1,x2-x1),l=Math.max(16,s.size*5);c.moveTo(x2,y2);c.lineTo(x2-l*Math.cos(a-.45),y2-l*Math.sin(a-.45));c.moveTo(x2,y2);c.lineTo(x2-l*Math.cos(a+.45),y2-l*Math.sin(a+.45))}c.stroke();c.restore()}
function drawObject(c,o){c.save();if(o.type==='text'){c.fillStyle=o.color||'#111';c.font=`${o.bold?'700 ':''}${o.size||30}px -apple-system, sans-serif`;c.textBaseline='top';const lines=String(o.text||'').split('\n');lines.forEach((l,i)=>c.fillText(l,o.x,o.y+i*(o.size||30)*1.25));}else if(o.type==='image'&&o.url){loadImage(o.url,im=>{c.drawImage(im,o.x,o.y,o.w,o.h)});}c.restore()}
function drawOverlay(){octx.clearRect(0,0,overlay.width,overlay.height);if(draftShape)drawShape(octx,draftShape);if(laserStroke){const s={...laserStroke,color:'#ff3434',size:10,tool:'pen'};octx.save();octx.shadowColor='#ff3434';octx.shadowBlur=18;drawStroke(octx,s);octx.restore()}if(selection){octx.save();octx.setLineDash([12,8]);octx.strokeStyle='#4d7dff';octx.lineWidth=2;octx.fillStyle='rgba(77,125,255,.08)';octx.fillRect(selection.x,selection.y,selection.w,selection.h);octx.strokeRect(selection.x,selection.y,selection.w,selection.h);octx.restore()}}

function pointFromEvent(e){const r=overlay.getBoundingClientRect(),p=page();return{x:(e.clientX-r.left)*p.width/r.width,y:(e.clientY-r.top)*p.height/r.height,p:e.pressure&&e.pressure>0?e.pressure:(e.pointerType==='mouse'?.55:.5),tx:e.tiltX||0,ty:e.tiltY||0,t:recordStart?(performance.now()-recordStart)/1000:null}}
function inputAllowed(e){if(sharedMode==='view')return false;if(e.pointerType==='pen'){penSeenAt=Date.now();$('#penStatus').textContent=`XP‑Pen / pen detected · pressure ${Math.round((e.pressure||0)*100)}%`;$('#pointerStatus').textContent='Pen';return true}$('#pointerStatus').textContent=e.pointerType==='touch'?'Touch':'Mouse';const po=sharedMode==='edit'?false:penOnlyPref();if(po&&e.pointerType!=='pen')return false;if(e.pointerType==='touch'&&Date.now()-penSeenAt<1000)return false;return true}
function pointerDown(e){if(!NOTE||!page()||!inputAllowed(e))return;if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();overlay.setPointerCapture?.(e.pointerId);const pnt=pointFromEvent(e);const stylusEraser=e.pointerType==='pen'&&(e.button===5||(e.buttons&32));const tool=stylusEraser?'eraser':TOOL;
  if(tool==='eraser'){pushUndo();eraseAt(pnt,Math.max(20,SIZE*4));renderCurrent();scheduleSave();return}
  if(tool==='text'){placeText(pnt);return}
  if(tool==='select'){
    if(selection&&pnt.x>=selection.x&&pnt.x<=selection.x+selection.w&&pnt.y>=selection.y&&pnt.y<=selection.y+selection.h){pushUndo();dragSelection={start:pnt,orig:clone(selection),indices:selectedStrokeIndices(selection)};return}
    selection={x:pnt.x,y:pnt.y,w:0,h:0,startX:pnt.x,startY:pnt.y};drawOverlay();return
  }
  if(['line','rect','ellipse','arrow'].includes(tool)){pushUndo();draftShape={id:uid(),kind:'shape',tool,color:COLOR,size:SIZE,x1:pnt.x,y1:pnt.y,x2:pnt.x,y2:pnt.y,t0:pnt.t};drawOverlay();return}
  if(tool==='laser'){laserStroke={id:uid(),tool:'pen',color:'#f33',size:12,pts:[pnt]};drawOverlay();return}
  pushUndo();activeStroke={id:uid(),tool,color:COLOR,size:SIZE,pts:[pnt],t0:pnt.t};
}
function pointerMove(e){if(!NOTE||!page())return;if(e.pointerType==='pen'){$('#penStatus').textContent=`XP‑Pen / pen · pressure ${Math.round((e.pressure||0)*100)}%`;penSeenAt=Date.now()}const pnt=pointFromEvent(e);
  if(activeStroke){const evs=(e.getCoalescedEvents&&e.getCoalescedEvents().length)?e.getCoalescedEvents():[e];for(const ev of evs)activeStroke.pts.push(ev===e?pnt:pointFromEvent(ev));drawOverlay();drawStroke(octx,activeStroke);return}
  if(draftShape){draftShape.x2=pnt.x;draftShape.y2=pnt.y;drawOverlay();return}
  if(laserStroke){laserStroke.pts.push(pnt);if(laserStroke.pts.length>80)laserStroke.pts.shift();drawOverlay();return}
  if(dragSelection){const dx=pnt.x-dragSelection.start.x,dy=pnt.y-dragSelection.start.y;const pp=page();for(const idx of dragSelection.indices){const s=pp.strokes[idx];if(s.kind==='shape'){s.x1+=dx;s.x2+=dx;s.y1+=dy;s.y2+=dy}else(s.pts||[]).forEach(pt=>{pt.x+=dx;pt.y+=dy})}dragSelection.start=pnt;selection.x+=dx;selection.y+=dy;renderCurrent();return}
  if(selection&&selection.startX!==undefined){selection.x=Math.min(selection.startX,pnt.x);selection.y=Math.min(selection.startY,pnt.y);selection.w=Math.abs(pnt.x-selection.startX);selection.h=Math.abs(pnt.y-selection.startY);drawOverlay()}
}
function pointerUp(e){if(!NOTE||!page())return;if(activeStroke){page().strokes.push(activeStroke);activeStroke=null;renderCurrent();renderPages();scheduleSave()}if(draftShape){page().strokes.push(draftShape);draftShape=null;renderCurrent();renderPages();scheduleSave()}if(laserStroke){setTimeout(()=>{laserStroke=null;drawOverlay()},300)}if(dragSelection){dragSelection=null;scheduleSave()}if(selection&&selection.startX!==undefined){delete selection.startX;delete selection.startY;drawOverlay()}}
function selectedStrokeIndices(box){const p=page();const arr=[];(p.strokes||[]).forEach((s,i)=>{if(s.kind==='shape'){const x=Math.min(s.x1,s.x2),y=Math.min(s.y1,s.y2),w=Math.abs(s.x2-s.x1),h=Math.abs(s.y2-s.y1);if(rectsIntersect(box,{x,y,w,h}))arr.push(i)}else if((s.pts||[]).some(pt=>pt.x>=box.x&&pt.x<=box.x+box.w&&pt.y>=box.y&&pt.y<=box.y+box.h))arr.push(i)});return arr}
function rectsIntersect(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function eraseAt(p,r){const pg=page();let best=-1,bestd=1e9;pg.strokes.forEach((s,i)=>{if(s.kind==='shape'){const d=Math.min(distPointSeg(p,{x:s.x1,y:s.y1},{x:s.x2,y:s.y2}),bestd);if(d<bestd){bestd=d;best=i}}else for(const q of s.pts||[]){const d=Math.hypot(p.x-q.x,p.y-q.y);if(d<bestd){bestd=d;best=i}}});if(best>=0&&bestd<r)pg.strokes.splice(best,1)}
function distPointSeg(p,a,b){const vx=b.x-a.x,vy=b.y-a.y,wx=p.x-a.x,wy=p.y-a.y,c1=vx*wx+vy*wy;if(c1<=0)return Math.hypot(p.x-a.x,p.y-a.y);const c2=vx*vx+vy*vy;if(c2<=c1)return Math.hypot(p.x-b.x,p.y-b.y);const t=c1/c2;return Math.hypot(p.x-(a.x+t*vx),p.y-(a.y+t*vy))}
function placeText(pnt){modal(`<div class="modalHead"><h2>Ajouter du texte</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="field"><label>Texte</label><textarea id="mtxt" rows="6"></textarea></div><div class="field"><label>Taille</label><input id="mts" type="number" min="12" max="120" value="32"></div><div class="modalActions"><button onclick="closeModal()">Cancel</button><button class="primary" id="mtok">Ajouter</button></div>`);$('#mtxt').focus();$('#mtok').onclick=()=>{const t=$('#mtxt').value;if(t){pushUndo();page().objects.push({id:uid(),type:'text',x:pnt.x,y:pnt.y,text:t,color:COLOR,size:+$('#mts').value||32});renderCurrent();scheduleSave()}closeModal()}}

function scheduleSave(){if(!NOTE||sharedMode==='view')return;$('#saveState').textContent='Modified…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,650)}
function savePayload(){return{title:NOTE.title,folder_id:NOTE.folder_id,kind:NOTE.kind,paper:NOTE.paper,favorite:NOTE.favorite,plain_text:NOTE.plain_text||'',transcript:NOTE.transcript||'',tags:NOTE.tags||'',content:NOTE.content}}
async function saveNow(){if(!NOTE||sharedMode==='view')return;if(saveInFlight){pendingSave=true;return}clearTimeout(saveTimer);saveInFlight=true;$('#saveState').textContent='Saving…';try{const n=await api('PUT',currentEndpoint(),savePayload());NOTE.revision=n.revision;NOTE.updated_at=n.updated_at;const m=S.notes.find(x=>x.id==NOTE.id);if(m)Object.assign(m,{title:NOTE.title,folder_id:NOTE.folder_id,kind:NOTE.kind,paper:NOTE.paper,favorite:NOTE.favorite,plain_text:NOTE.plain_text,transcript:NOTE.transcript,updated_at:NOTE.updated_at,revision:NOTE.revision});$('#saveState').textContent='Saved'}catch(e){$('#saveState').textContent='Error';toast('Save error: '+e.message)}finally{saveInFlight=false;if(pendingSave){pendingSave=false;saveNow()}}}

async function importFiles(e){const files=[...e.target.files];e.target.value='';if(sharedMode==='view'||!files.length)return;if(!NOTE){await App.newNote()}for(const f of files){if(f.name.toLowerCase().endsWith('.vnote')){try{const data=JSON.parse(await f.text());if(data.content){NOTE.content=normalizeContent(data.content,data.paper||NOTE.paper);NOTE.title=data.title||NOTE.title;NOTE.paper=data.paper||NOTE.paper;NOTE.kind=['notebook','pdf'].includes(data.kind)?data.kind:'notebook';NOTE.tags=data.tags||'';NOTE.plain_text=data.plain_text||'';NOTE.transcript=data.transcript||'';PAGE=NOTE.content.activePage||0;hydrateEditor();scheduleSave();toast('VanoNote imported')}}catch(err){toast('Invalid .vnote file')}continue}
    let kind='file';if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'))kind='pdf';else if(f.type.startsWith('image/'))kind='image';else if(/\.(docx?|odt)$/i.test(f.name))kind='document';else if(/\.(pptx?|odp)$/i.test(f.name))kind='slides';
    toast('Import de '+f.name+'…');const share=sharedToken?`&share=${encodeURIComponent(sharedToken)}`:'';const url=`/api/upload?note_id=${NOTE.id}&kind=${encodeURIComponent(kind)}&name=${encodeURIComponent(f.name)}${share}`;const r=await fetch(url,{method:'POST',headers:{'Content-Type':f.type||'application/octet-stream'},body:f});const o=await r.json();if(!r.ok){toast(o.error||'Import impossible');continue}
    NOTE.attachments=NOTE.attachments||[];NOTE.attachments.push(o);
    if(o.pages?.length){NOTE.kind='pdf';NOTE.content.pages=o.pages.map((pg,i)=>({id:uid(),name:'Page '+(i+1),paper:'blank',width:pg.width||1200,height:pg.height||1600,strokes:[],objects:[],background:{url:pg.url,type:'pdf',attachment_id:o.id,page:i+1}}));PAGE=0;hydrateEditor();scheduleSave();toast(`${o.pages.length} PDF pages ready to annotate`)}
    else if(kind==='image'){const im=await loadImagePromise(o.url);const p=page(),maxW=p.width*.8,maxH=p.height*.8,sc=Math.min(maxW/im.naturalWidth,maxH/im.naturalHeight,1);pushUndo();p.objects.push({id:uid(),type:'image',url:o.url,x:80,y:80,w:im.naturalWidth*sc,h:im.naturalHeight*sc});renderCurrent();scheduleSave();toast('Image added')}
    else if(o.render_error)toast(o.render_error);renderAttachments();
  }}
function loadImagePromise(url){return new Promise((res,rej)=>loadImage(url,res,()=>rej(new Error('Image unavailable'))))}
function renderAttachments(){if(!NOTE)return;const a=NOTE.attachments||[];$('#attachmentList').innerHTML=a.length?a.map(x=>`<div class="attachment"><span>${x.kind==='audio'?'♪':x.kind==='pdf'?'PDF':'▧'}</span><a href="${x.url}" target="_blank">${esc(x.name)}</a></div>`).join(''):'<div class="listEmpty" style="padding:12px">No attachments</div>';const aud=a.filter(x=>x.kind==='audio');$('#audioList').innerHTML=aud.map(x=>`<div class="audioItem"><audio controls src="${x.url}"></audio><a href="${x.url}" target="_blank">↗</a></div>`).join('')}

async function toggleRecording(){if(sharedMode==='view')return;if(mediaRecorder&&mediaRecorder.state==='recording')return stopRecording();try{audioStream=await navigator.mediaDevices.getUserMedia({audio:true});mediaChunks=[];const mime=MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?'audio/webm;codecs=opus':'';mediaRecorder=new MediaRecorder(audioStream,mime?{mimeType:mime}:undefined);mediaRecorder.ondataavailable=e=>{if(e.data.size)mediaChunks.push(e.data)};mediaRecorder.onstop=saveRecording;mediaRecorder.start(500);recordStart=performance.now();$('#recordStatus').textContent='Recording';$('#recordToggle').textContent='Stop';$('#audioBtn').classList.add('primary');recordTick=setInterval(()=>$('#recordTimer').textContent=fmtTime((performance.now()-recordStart)/1000),500);toast('Audio recording started');if(!transcribing)startTranscription(false)}catch(e){toast('Microphone unavailable: '+e.message)}}
function stopRecording(){if(mediaRecorder?.state==='recording')mediaRecorder.stop();audioStream?.getTracks().forEach(t=>t.stop());clearInterval(recordTick);$('#recordToggle').textContent='Record';$('#audioBtn').classList.remove('primary');$('#recordStatus').textContent='Recording finished'}
async function saveRecording(){if(!mediaChunks.length||!NOTE)return;const blob=new Blob(mediaChunks,{type:mediaRecorder.mimeType||'audio/webm'});const name=`${NOTE.title||'note'}_${new Date().toISOString().replace(/[:.]/g,'-')}.webm`;try{const share=sharedToken?`&share=${encodeURIComponent(sharedToken)}`:'';const r=await fetch(`/api/upload?note_id=${NOTE.id}&kind=audio&name=${encodeURIComponent(name)}${share}`,{method:'POST',headers:{'Content-Type':blob.type},body:blob});const o=await r.json();if(!r.ok)throw new Error(o.error||'Upload failed');NOTE.attachments.push(o);renderAttachments();toast('Audio saved in VanoNote/audio')}catch(e){toast('Error audio: '+e.message)}recordStart=0;mediaChunks=[];scheduleSave()}
function speechCtor(){return window.SpeechRecognition||window.webkitSpeechRecognition}
function toggleTranscription(){transcribing?stopTranscription():startTranscription(true)}
function startTranscription(showToast=true){const C=speechCtor();if(!C){if(showToast)toast('Browser transcription is not available in this browser');return}recognition=new C();recognition.lang='en-CA';recognition.continuous=true;recognition.interimResults=true;let base=NOTE?.transcript||'';recognition.onresult=e=>{let final='',interim='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)final+=t+' ';else interim+=t}if(final){base=(base+(base?' ':'')+final.trim()).trim();NOTE.transcript=base;scheduleSave()}$('#transcript').innerText=(base+(interim?' '+interim:'')).trim()};recognition.onend=()=>{if(transcribing)try{recognition.start()}catch{}};try{recognition.start();transcribing=true;$('#transcribeBtn').classList.add('primary');if(showToast)toast('Live transcription enabled')}catch(e){toast(e.message)}}
function stopTranscription(){transcribing=false;try{recognition?.stop()}catch{}$('#transcribeBtn').classList.remove('primary');if(NOTE){NOTE.transcript=$('#transcript').innerText;scheduleSave()}}

function openTemplates(){if(!NOTE)return toast('Open a note');if(sharedMode==='view')return toast('Read-only student view');const items=[['blank','Blank'],['ruled','Ruled'],['grid','Grid'],['dots','Dots'],['cornell','Cornell'],['blackboard','Blackboard']];modal(`<div class="modalHead"><h2>Paper & templates</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="templateGrid">${items.map(([k,n])=>`<button class="template" data-paper="${k}"><div class="paperPreview" data-pv="${k}"></div><b>${n}</b></button>`).join('')}</div><div class="modalActions"><button id="applyAllPaper">Apply to all pages</button></div>`);$$('.template').forEach(b=>b.onclick=()=>{page().paper=b.dataset.paper;NOTE.paper=b.dataset.paper;renderCurrent();renderPages();scheduleSave();closeModal()});$('#applyAllPaper').onclick=()=>{const paper=page().paper;NOTE.content.pages.forEach(p=>p.paper=paper);renderCurrent();renderPages();scheduleSave();closeModal()};$$('[data-pv]').forEach(d=>{const k=d.dataset.pv;if(k==='grid')d.style.backgroundImage='linear-gradient(#d9e3df 1px,transparent 1px),linear-gradient(90deg,#d9e3df 1px,transparent 1px)',d.style.backgroundSize='14px 14px';if(k==='ruled')d.style.backgroundImage='repeating-linear-gradient(#fff 0,#fff 13px,#ccdaea 14px)';if(k==='dots')d.style.backgroundImage='radial-gradient(#9fa9a5 1px,transparent 1px)',d.style.backgroundSize='14px 14px';if(k==='blackboard')d.style.background='#173128';if(k==='cornell')d.style.background='linear-gradient(90deg,transparent 29%,#c9baa2 30%,transparent 31%),linear-gradient(0deg,transparent 18%,#c9baa2 19%,transparent 20%),#fff'})}
function openShare(){if(!NOTE||sharedToken)return;modal(`<div class="modalHead"><h2>Share with students</h2><button class="modalClose" onclick="closeModal()">×</button></div><p style="color:var(--mut);font-size:12px">The link works on the same Wi-Fi network or through Tailscale. For Zoom/Meet/Teams, you can also share the VanoNote window directly.</p><div class="field"><label>Mode</label><select id="shareMode"><option value="view">Read only — students watch</option><option value="edit">Collaborative — students can write</option><option value="none">Disable sharing</option></select></div><div id="shareResult"></div><div class="modalActions"><button onclick="closeModal()">Close</button><button class="primary" id="shareGo">Create / update link</button></div>`);$('#shareMode').value=NOTE.share_mode||'view';$('#shareGo').onclick=async()=>{const r=await api('POST',`/api/notes/${NOTE.id}/share`,{mode:$('#shareMode').value});NOTE.share_mode=r.mode;NOTE.share_token=r.token;$('#shareResult').innerHTML=r.url?`<div class="field"><label>Student link</label><input id="shareUrl" value="${esc(r.url)}" readonly></div><div style="display:flex;gap:6px"><button id="copyShare" class="primary" style="padding:7px 10px;border-radius:7px">Copy</button><button id="openShare" style="padding:7px 10px;border:1px solid var(--line);border-radius:7px">Open student view</button></div>`:'<p>Sharing disabled.</p>';if(r.url){$('#copyShare').onclick=()=>navigator.clipboard.writeText(r.url).then(()=>toast('Link copied'));$('#openShare').onclick=()=>window.open(r.url,'_blank')}}}
function enterPresentation(){if(!NOTE)return;document.body.classList.add('presentation');$('#classbar').classList.remove('hidden');$('#classInfo').textContent='Teacher whiteboard';fitZoom();try{document.documentElement.requestFullscreen?.()}catch{}}
function exitPresentation(){document.body.classList.remove('presentation');if(!sharedToken)$('#classbar').classList.add('hidden');if(document.fullscreenElement)document.exitFullscreen?.();fitZoom()}
function openMore(){if(!NOTE)return;if(sharedMode==='view')return toast('Read-only student view');if(NOTE.deleted_at){modal(`<div class="modalHead"><h2>Trash actions</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="modalList"><button class="wide primary" id="restoreAct">↶ Restore note</button><button class="wide" id="permanentAct" style="color:var(--red)">⌫ Delete permanently</button></div>`);$('#restoreAct').onclick=restoreNote;$('#permanentAct').onclick=deletePermanent;return}modal(`<div class="modalHead"><h2>Note actions</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="modalList"><button class="wide" id="favAct">${NOTE.favorite?'☆ Remove from favorites':'★ Add to favorites'}</button><button class="wide" id="moveAct">▣ Move to folder</button><button class="wide" id="dupAct">⧉ Duplicate</button><button class="wide" id="exportAct">↥ Export .vnote</button><button class="wide" id="printAct">⎙ Print / Save PDF</button><button class="wide" id="histAct">◷ Version history</button><button class="wide" id="delPageAct">⌫ Delete this page</button><button class="wide" id="trashAct" style="color:var(--red)">⌫ Move to Trash</button></div>`);$('#favAct').onclick=()=>{NOTE.favorite=NOTE.favorite?0:1;scheduleSave();const m=S.notes.find(n=>n.id==NOTE.id);if(m)m.favorite=NOTE.favorite;closeModal();renderLibrary();renderList()};$('#moveAct').onclick=openMove;$('#dupAct').onclick=duplicateNote;$('#exportAct').onclick=exportVnote;$('#printAct').onclick=printNote;$('#histAct').onclick=openHistory;$('#delPageAct').onclick=()=>{closeModal();deletePage()};$('#trashAct').onclick=trashNote}
function openMove(){modal(`<div class="modalHead"><h2>Move note</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="field"><label>Folder</label><select id="moveFolder"><option value="">No folder</option>${S.folders.map(f=>`<option value="${f.id}" ${NOTE.folder_id==f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><div class="modalActions"><button onclick="closeModal()">Cancel</button><button class="primary" id="moveOk">Move</button></div>`);$('#moveOk').onclick=()=>{NOTE.folder_id=+$('#moveFolder').value||null;scheduleSave();const m=S.notes.find(n=>n.id==NOTE.id);if(m)m.folder_id=NOTE.folder_id;closeModal();renderLibrary();renderList()}}
async function duplicateNote(){const n=await api('POST',`/api/notes/${NOTE.id}/duplicate`,{});S.notes.unshift({...n,content:undefined,attachments:undefined});closeModal();renderLibrary();renderList();selectNote(n.id);toast('Note duplicated')}
function exportVnote(){const data={format:'VanoNote',version:1,title:NOTE.title,folder:folderName(NOTE.folder_id),kind:NOTE.kind,paper:NOTE.paper,plain_text:NOTE.plain_text,transcript:NOTE.transcript,tags:NOTE.tags,content:NOTE.content,exported_at:new Date().toISOString()};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});downloadBlob(blob,(NOTE.title||'VanoNote').replace(/[^\w\- ]/g,'_')+'.vnote');closeModal()}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
async function printNote(){closeModal();const w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print this note');const pages=NOTE.content.pages;const urls=[];for(const p of pages){if(p.background?.url)urls.push(hiUrl(p.background.url));for(const o of p.objects||[])if(o.type==='image'&&o.url)urls.push(o.url)}await Promise.all([...new Set(urls)].map(u=>loadImagePromise(u).catch(()=>null)));const imgs=[];for(const p of pages){const c=document.createElement('canvas');c.width=p.width;c.height=p.height;const cc=c.getContext('2d');drawPageTo(cc,p,p.width,p.height,false);imgs.push(c.toDataURL('image/png'))}w.document.write(`<html><head><title>${esc(NOTE.title)}</title><style>@page{margin:0}body{margin:0;background:#fff}.p{page-break-after:always;width:100vw;display:block}</style></head><body>${imgs.map(x=>`<img class="p" src="${x}">`).join('')}<script>onload=()=>setTimeout(()=>print(),500)<\/script></body></html>`);w.document.close()}
async function openHistory(){const rows=await api('GET',`/api/notes/${NOTE.id}/versions`);modal(`<div class="modalHead"><h2>Version history</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="modalList">${rows.length?rows.map(v=>`<div class="versionRow"><span>${esc(v.title)} · ${new Date(v.created_at).toLocaleString('en-CA')}</span><button data-v="${v.id}">Restore</button></div>`).join(''):'<div class="listEmpty">No previous versions yet.</div>'}</div>`);$$('.versionRow button').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this version?'))return;NOTE=await api('POST',`/api/notes/${NOTE.id}/restore-version/${b.dataset.v}`,{});NOTE.content=NOTE.content||defaultContent();closeModal();hydrateEditor();toast('Version restored')})}
async function trashNote(){const id=NOTE.id;if(!confirm('Move this note to Trash?'))return;await api('DELETE','/api/notes/'+id);const m=S.notes.find(n=>n.id==id);if(m)m.deleted_at=new Date().toISOString();NOTE=null;closeModal();$('#editor').classList.add('hidden');$('#emptyState').classList.remove('hidden');$('#noteTitle').value='';renderLibrary();renderList();history.replaceState(null,'','/');toast('Note moved to Trash')}
async function restoreNote(){const n=await api('POST',`/api/notes/${NOTE.id}/restore`,{});const m=S.notes.find(x=>x.id==n.id);if(m)Object.assign(m,n,{content:undefined,attachments:undefined});NOTE=n;closeModal();renderLibrary();renderList();toast('Note restored')}
async function deletePermanent(){const id=NOTE.id;if(!confirm('Permanently delete this note and its files? This cannot be undone.'))return;await api('DELETE',`/api/notes/${id}/permanent`);S.notes=S.notes.filter(n=>n.id!==id);NOTE=null;closeModal();$('#editor').classList.add('hidden');$('#emptyState').classList.remove('hidden');$('#noteTitle').value='';renderLibrary();renderList();history.replaceState(null,'','/');toast('Note permanently deleted')}

function localSummary(){if(!NOTE)return;const txt=((NOTE.plain_text||'')+' '+(NOTE.transcript||'')).replace(/\s+/g,' ').trim();if(!txt){$('#studyOutput').innerHTML='<div class="studyCard">Add text or a transcript to generate a summary.</div>';return}const sentences=txt.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[txt];const picks=sentences.filter(s=>s.trim().length>25).slice(0,7);$('#studyOutput').innerHTML='<div class="studyCard"><b>Summary</b><ul>'+picks.map(s=>'<li>'+esc(s.trim())+'</li>').join('')+'</ul></div>'}
function generateCards(){if(!NOTE)return;const txt=((NOTE.plain_text||'')+' '+(NOTE.transcript||'')).replace(/\s+/g,' ').trim();const sentences=(txt.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[]).filter(s=>s.trim().length>35).slice(0,12);const cards=sentences.map((s,i)=>{const words=s.trim().split(/\s+/);const idx=Math.min(words.length-1,Math.max(2,Math.floor(words.length*.45)));const ans=words[idx].replace(/[.,;:!?]/g,'');words[idx]='_____';return{q:words.join(' '),a:ans}});NOTE._cards=cards;$('#studyOutput').innerHTML=cards.length?cards.map((c,i)=>`<div class="studyCard"><b>Card ${i+1}</b>${esc(c.q)}<details><summary>Answer</summary>${esc(c.a)}</details></div>`).join(''):'<div class="studyCard">Not enough text to generate flashcards.</div>'}
function runQuiz(){if(!NOTE._cards?.length)generateCards();const cards=NOTE._cards||[];if(!cards.length)return;let i=0,score=0;const show=()=>{const c=cards[i];$('#studyOutput').innerHTML=`<div class="studyCard"><b>Question ${i+1}/${cards.length}</b><p>${esc(c.q)}</p><input id="quizAns" style="width:100%;padding:7px"><button id="quizCheck" class="wide primary" style="margin-top:7px">Check</button></div>`;$('#quizCheck').onclick=()=>{const ok=$('#quizAns').value.trim().toLowerCase()===c.a.toLowerCase();if(ok)score++;toast(ok?'Correct':'Answer: '+c.a);i++;if(i<cards.length)setTimeout(show,400);else $('#studyOutput').innerHTML=`<div class="studyCard"><b>Result</b>${score} / ${cards.length}</div>`}};show()}
function insertLatex(){const ta=$('#plainText');const t='\\[\n  % LaTeX equation\n\\]';const a=ta.selectionStart,b=ta.selectionEnd;ta.value=ta.value.slice(0,a)+t+ta.value.slice(b);NOTE.plain_text=ta.value;scheduleSave();ta.focus();ta.selectionStart=ta.selectionEnd=a+3}
function wrapTypedText(mark){if(!NOTE||sharedMode==='view')return;const ta=$('#plainText'),a=ta.selectionStart,b=ta.selectionEnd,selected=ta.value.slice(a,b);ta.value=ta.value.slice(0,a)+mark+selected+mark+ta.value.slice(b);NOTE.plain_text=ta.value;scheduleSave();ta.focus();ta.selectionStart=a+mark.length;ta.selectionEnd=b+mark.length}

async function backup(){try{const r=await api('POST','/api/backup',{});toast('Backup created in VanoNote/backups');modal(`<div class="modalHead"><h2>VanoNote Backup</h2><button class="modalClose" onclick="closeModal()">×</button></div><p>The backup was created in the <b>backups</b> folder of VanoNote.</p><div class="modalActions"><a href="${r.url}" style="padding:8px 12px;background:var(--acc);color:#fff;border-radius:8px;text-decoration:none">Download a copy</a></div>`)}catch(e){toast(e.message)}}
function openSettings(){const pen=penOnlyPref();modal(`<div class="modalHead"><h2>VanoNote Settings</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="field"><label>Data folder</label><input readonly value="~/Desktop/app/VanoNote/ — data, attachments, audio, exports and backups"></div><div class="field"><label>XP‑Pen / pen</label><select id="setPen"><option value="0" ${!pen?'selected':''}>Mouse, trackpad and pen all draw (recommended)</option><option value="1" ${pen?'selected':''}>Pen only (the mouse and touch do not draw)</option></select></div><div class="field"><label>Shortcuts to map to XP‑Pen buttons</label><textarea readonly rows="5">P = Pen    H = Highlighter    E = Eraser    L = Laser\nV = Lasso    T = Text         C = Calligraphy\nZ = Undo  Shift+Z = Redo   [ / ] = Size\nF = Presentation   ← / → = Pages</textarea></div><div class="field"><label>PDF</label><input readonly value="${S.fitz?'PyMuPDF installed — full PDF import':'PyMuPDF missing — run install_dependencies.command'}"></div><div class="modalActions"><button class="primary" id="setOk">Save</button></div>`);$('#setOk').onclick=()=>{const v=$('#setPen').value==='1';try{localStorage.setItem('vn_penonly',v?'1':'0')}catch(e){}$('#penOnlyBtn').classList.toggle('on',v);closeModal()}}
function openSplit(){if(!NOTE)return;const opts=S.notes.filter(n=>!n.deleted_at&&n.id!==NOTE.id);if(!opts.length)return toast('No other note');modal(`<div class="modalHead"><h2>Split note</h2><button class="modalClose" onclick="closeModal()">×</button></div><div class="field"><label>Open a reference note on the right</label><select id="splitSel">${opts.map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('')}</select></div><div class="modalActions"><button class="primary" id="splitOk">Open</button></div>`);$('#splitOk').onclick=async()=>{const n=await api('GET','/api/notes/'+$('#splitSel').value);closeModal();document.querySelector('.splitReference')?.remove();const d=document.createElement('div');d.className='splitReference';d.innerHTML=`<header><b>${esc(n.title)}</b><button>×</button></header><div class="refbody">${esc(n.plain_text||n.transcript||'Handwritten note — use the page list to view it in VanoNote.')}</div>`;d.querySelector('button').onclick=()=>d.remove();$('#canvasViewport').appendChild(d)}}
const THEME_LABELS={autumn:'☀ Autumn',night:'☾ Night',quantum:'✦ Quantum'};
function applyTheme(t){if(!THEME_LABELS[t])t='autumn';document.documentElement.dataset.theme=t==='autumn'?'':t;localStorage.setItem('vn_theme',t);const b=$('#themeBtn');if(b)b.textContent=THEME_LABELS[t]}
function toggleTheme(){const a=['autumn','night','quantum'],c=localStorage.getItem('vn_theme')||'autumn',n=a[(a.indexOf(c)+1)%a.length];applyTheme(n);toast('Theme: '+THEME_LABELS[n].replace(/^[^ ]+ /,''))}

function keyHandler(e){const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA'].includes(tag)||document.activeElement?.isContentEditable){if(e.key==='Escape')document.activeElement.blur();return}if(e.key==='Escape'){exitPresentation();selection=null;drawOverlay();closeModal();return}const k=e.key.toLowerCase();if(k==='p')setTool('pen');else if(k==='c')setTool('calligraphy');else if(k==='h')setTool('highlighter');else if(k==='e')setTool('eraser');else if(k==='l')setTool('laser');else if(k==='v')setTool('select');else if(k==='t')setTool('text');else if(k==='f')enterPresentation();else if(k==='z'&&!e.shiftKey){e.preventDefault();undo()}else if((k==='z'&&e.shiftKey)||k==='y'){e.preventDefault();redo()}else if(e.key==='[')setSize(SIZE-1);else if(e.key===']')setSize(SIZE+1);else if(e.key==='ArrowRight'&&document.body.classList.contains('presentation'))setPage(PAGE+1);else if(e.key==='ArrowLeft'&&document.body.classList.contains('presentation'))setPage(PAGE-1);else if((e.key==='Delete'||e.key==='Backspace')&&selection){const inds=selectedStrokeIndices(selection).sort((a,b)=>b-a);if(inds.length){pushUndo();inds.forEach(i=>page().strokes.splice(i,1));selection=null;renderCurrent();scheduleSave()}}}

window.closeModal=closeModal;
window.addEventListener('pagehide',()=>{if(NOTE&&sharedMode!=='view'){clearTimeout(saveTimer);try{fetch(currentEndpoint(),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(savePayload()),keepalive:true})}catch{}}});
boot().catch(e=>{console.error(e);toast('Error VanoNote: '+e.message)});
